import pytest

def test_partition_all_inaccurate_len():
    import pytest
    from toolz.itertoolz import partition_all, no_pad

    class InaccurateLenIterator:
        def __init__(self, iterator, length):
            self.iterator = iterator
            self.length = length

        def __iter__(self):
            return self

        def __next__(self):
            return next(self.iterator)

        def __len__(self):
            return self.length

    def gen():
        for i in range(5):
            yield i

    seq = InaccurateLenIterator(gen(), 7)
    try:
        result = list(partition_all(10, seq))
    except Exception as e:
        pytest.fail(f"partition_all raised an exception: {e}")

    assert len(result) == 1
    batch = result[0]
    assert len(batch) == 5
    assert batch == (0, 1, 2, 3, 4)
    assert no_pad not in batch

